production.solution:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract UserRegistry {
    struct Profile {
        uint256 score;
        bool active;
    }

    mapping(address => Profile) public profiles;

    function register() external {
        require(!profiles[msg.sender].active, "Al geregistreerd");
        profiles[msg.sender].active = true;
    }

    function addScore(address user, uint256 points) external {
        require(profiles[user].active, "Niet geregistreerd");
        profiles[user].score += points;
    }

    function isActive(address u) external view returns (bool) {
        return profiles[u].active;
    }
    function getScore(address u) external view returns (uint256) {
        return profiles[u].score;
    }
}
